use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5);


    let agent = AgentBuilder::new(model)
        .preamble("You are a helpful assistant.")
        .temperature(0.7)
        .build();


    let response = agent.prompt("Hello!").await?;
    println!("{}", response.output());


    Ok(())
}

let response = tool_agent
    .prompt("Please calculate 2 + 5, then multiply the result by 3")
    .max_turns(5) // two rounds of tool calls plus the answer, with room to spare
    .await?;


println!("{response}");

let response = agent.prompt("What is 2 + 2?").max_turns(3).await?;


println!("answer: {}", response.output());
println!(
    "tokens: {:?} in / {:?} out across {} model calls",
    response.usage.input_tokens,
    response.usage.output_tokens,
    response.requests(),
);
println!("messages produced by this run: {}", response.messages.len());

#[derive(Debug, serde::Deserialize, schemars::JsonSchema)]
struct Forecast {
    city: String,
    temperature_f: f64,
}


let forecast: Forecast = agent
    .prompt_typed::<Forecast>("Give me a plausible forecast for New York.")
    .retries(1) // re-run once if the output doesn't parse as `Forecast`
    .await?
    .output;


println!("{} will be {}°F", forecast.city, forecast.temperature_f);

let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a calculator. Use the tools to compute results.")
    .tool(Add)
    .default_max_turns(3) // tool call(s), then the answer
    .build();


let response = agent.prompt("What is 2 + 5?").await?;

use rig::message::ToolChoice;


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a calculator. Always compute with tools, never in your head.")
    .tool_choice(ToolChoice::Required) // the model must call a tool before answering
    .build();

let model = OpenAI::from_env()?.completion(openai::GPT_5_5).erase();


// The worker: a specialised sub-agent.
let bob = AgentBuilder::new(model.clone())
    .name("bob")
    .description("An employee who handles admin tasks at FooBar Inc.")
    .preamble("You are Bob, an admin employee. Your manager Alice may ask you to do things.")
    .build();


// The manager: prompts Bob by calling him as a tool.
let alice = AgentBuilder::new(model)
    .name("alice")
    .preamble("You are Alice, a manager in the admin department. You manage Bob.")
    .dynamic_tool(bob.into_tool()?)
    .build();


let response = alice
    .prompt("Ask Bob to draft a welcome email and tell me what he wrote.")
    .max_turns(3)
    .await?;


println!("{response}");

use rig::agent::{AgentHook, HookContext, ModelSelection, ModelSelectionAction};


/// A cheap model for the first call; the stronger one once tool results are in.
struct CheapFirst;


impl AgentHook for CheapFirst {
    fn on_model_select(&self, ctx: &HookContext, _event: ModelSelection<'_>) -> ModelSelectionAction {
        if ctx.turn() == 1 {
            ModelSelectionAction::select("fast")
        } else {
            ModelSelectionAction::select("strong")
        }
    }
}


let client = OpenAI::from_env()?;
let agent = AgentBuilder::named_model("fast", client.completion(openai::GPT_5_4_MINI))
    .model_route("strong", client.completion(openai::GPT_5_5))
    .add_hook(CheapFirst)
    .build();


// Or skip the hook and pick one model for a whole run:
let response = agent.prompt("Summarize Rust's ownership rules.").using_model("strong").await?;

use rig::completion::Effort;


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a helpful agent.")
    .reasoning(Effort::High)
    .additional_params(json!({ "user": "user-42" }))
    .build();
